function validate([orders]) {
  if (!Array.isArray(orders) || orders.length < 1 || orders.length > 50000) return 'orders needs 1 to 50000 entries.';
  for (const order of orders) {
    if (!Array.isArray(order) || order.length !== 3 || order.some(v => typeof v !== 'string')) return 'Each order is three strings.';
    const [name, table, food] = order;
    if (name.length < 1 || name.length > 20 || !/^[A-Za-z ]+$/.test(name)) return 'Customer names are 1 to 20 letters or spaces.';
    if (food.length < 1 || food.length > 20 || !/^[A-Za-z ]+$/.test(food)) return 'Food items are 1 to 20 letters or spaces.';
    if (!/^[1-9]\d{0,2}$/.test(table) || Number(table) > 500) return 'Table numbers are integers from 1 to 500 without leading zeros.';
  }
  return null;
}

