function displayTable(orders) {
  const counts = new Map();
  const foods = new Set();

  for (const [, table, food] of orders) {
    foods.add(food);
    if (!counts.has(table)) {
      counts.set(table, new Map());
    }
    const tableCounts = counts.get(table);
    tableCounts.set(food, (tableCounts.get(food) || 0) + 1);
  }

  const header = [...foods].sort();
  const tables = [...counts.keys()].sort((a, b) => Number(a) - Number(b));
  const result = [["Table", ...header]];

  for (const table of tables) {
    const tableCounts = counts.get(table);
    const row = [table];
    for (const food of header) {
      row.push(String(tableCounts.get(food) || 0));
    }
    result.push(row);
  }
  return result;
}

