function displayTable(orders) {
  const foodList = [];
  const tableList = [];
  for (const order of orders) {
    if (!foodList.includes(order[2])) foodList.push(order[2]);
    if (!tableList.includes(order[1])) tableList.push(order[1]);
  }
  // Insertion sorts with explicit comparisons.
  for (let i = 1; i < foodList.length; i++)
    for (let j = i; j > 0 && foodList[j - 1] > foodList[j]; j--) [foodList[j - 1], foodList[j]] = [foodList[j], foodList[j - 1]];
  for (let i = 1; i < tableList.length; i++)
    for (let j = i; j > 0 && parseInt(tableList[j - 1], 10) > parseInt(tableList[j], 10); j--) [tableList[j - 1], tableList[j]] = [tableList[j], tableList[j - 1]];
  const out = [["Table"].concat(foodList)];
  for (const t of tableList) {
    const line = [t];
    for (const f of foodList) {
      let c = 0;
      for (const order of orders) if (order[1] === t && order[2] === f) c++;
      line.push("" + c);
    }
    out.push(line);
  }
  return out;
}

