function generate(rand, size) {
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const letters = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ";
  const word = (maxLen) => {
    const len = 1 + Math.floor(rand() * maxLen);
    let s = "";
    for (let i = 0; i < len; i++) s += (i > 0 && i < len - 1 && rand() < 0.15) ? " " : letters[Math.floor(rand() * letters.length)];
    return s;
  };
  if (size === 'large') {
    const foods = Array.from({ length: 60 }, () => word(20));
    const n = 2000;
    const orders = [];
    for (let i = 0; i < n; i++) orders.push([word(20), String(1 + Math.floor(rand() * 500)), pick(foods)]);
    return [orders];
  }
  const foodPool = ["Soda", "soda", "Water", "Ice Cream", "IceCream", "Ice", "a", "B", "Beef Burrito", "Bean Burrito", word(6), word(6)];
  const names = ["Ann", "Bo", "Cy", "Dee", "Eli"];
  const tablePool = ["1", "2", "3", "9", "10", "11", "20", "100", "500"];
  const tables = tablePool.filter(() => rand() < 0.5);
  if (!tables.length) tables.push(pick(tablePool));
  const n = 1 + Math.floor(rand() * 9);
  const orders = [];
  for (let i = 0; i < n; i++) orders.push([pick(names), pick(tables), pick(foodPool)]);
  return [orders];
}
